def _pairs(items: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in items:
        if key in result: raise ValueError("duplicate JSON key")
        result[key] = value
    return result
def _parse(data: str | bytes) -> object:
    text = data.decode("utf-8", errors="strict") if isinstance(data, bytes) else data
    _validate_json_text(text)
    return json.loads(text, parse_float=Decimal, object_pairs_hook=_pairs, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
def decode_authoring(data: str | bytes) -> AROPError:
    return _decode_AROPError(_parse(data), False)
def decode_forward(data: str | bytes) -> AROPError:
    document = _parse(data); value = _decode_AROPError(document, True); value._forward_wire = _json_value(document); return value
def _to_wire(value):
    if isinstance(value, (AROPError, AgentManifest, AssetRef)) and value._forward_wire is not UNSET: return value._forward_wire
    if value is UNSET: raise ValueError("UNSET has no wire representation")
    if is_dataclass(value):
        result = {("$ref" if item.name == "ref" else item.name): _to_wire(getattr(value, item.name)) for item in fields(value) if not item.name.startswith("_") and getattr(value, item.name) is not UNSET}
        additional = getattr(value, "_additional_properties", UNSET)
        if isinstance(additional, dict): result.update({key: _to_wire(item) for key, item in additional.items()})
        elif additional is not UNSET: raise ValueError("invalid additional properties")
        return result
    if isinstance(value, list): return [_to_wire(item) for item in value]
    if isinstance(value, dict): return {key: _to_wire(item) for key, item in value.items()}
    return value
def encode_wire(value: AROPError) -> str:
    return json.dumps(_to_wire(value), ensure_ascii=False, separators=(",", ":"), sort_keys=True)

